from __future__ import annotations

import re
import subprocess
import urllib.request

from secretscan.model import DockerContainer, DockerStatus, Module, ModuleStatus


def _parse_ports(ports_str: str) -> tuple[list[str], bool]:
    ports: list[str] = []
    exposed = False
    for part in ports_str.split(","):
        part = part.strip()
        if not part:
            continue
        ports.append(part)
        if "0.0.0.0:" in part or ":::" in part:
            exposed = True
    return ports, exposed


def docker_scan() -> tuple[DockerStatus, ModuleStatus]:
    status = ModuleStatus(module=Module.DOCKER)
    ds = DockerStatus()

    try:
        ver = subprocess.run(
            ["docker", "version", "--format", "{{.Server.Version}}"],
            capture_output=True, text=True, timeout=10,
        )
        ds.installed = ver.returncode == 0
    except (subprocess.SubprocessError, FileNotFoundError):
        status.note = "Docker not installed or not on PATH"
        return ds, status

    if not ds.installed:
        status.note = "Docker not installed or not on PATH"
        return ds, status

    try:
        ps = subprocess.run(
            ["docker", "ps", "--format", "{{.ID}}\t{{.Names}}\t{{.Image}}\t{{.Status}}\t{{.Ports}}"],
            capture_output=True, text=True, timeout=10,
        )
        ds.daemon_running = ps.returncode == 0
    except (subprocess.SubprocessError, FileNotFoundError):
        status.note = "Docker daemon not running"
        return ds, status

    if ds.daemon_running:
        status.attempted += 1
        status.accessed += 1
        for line in ps.stdout.strip().splitlines():
            parts = line.split("\t")
            if len(parts) < 4:
                continue
            ports_str = parts[4] if len(parts) > 4 else ""
            ports, exposed = _parse_ports(ports_str)
            ds.containers.append(DockerContainer(
                container_id=parts[0],
                name=parts[1],
                image=parts[2],
                status=parts[3],
                ports=ports,
                exposed=exposed,
            ))

    try:
        req = urllib.request.Request("http://127.0.0.1:2375/version", method="GET")
        with urllib.request.urlopen(req, timeout=2) as resp:
            ds.api_exposed = resp.status == 200
    except Exception:
        ds.api_exposed = False

    if ds.api_exposed:
        status.note = "WARNING: Docker Engine API is listening in plaintext on localhost:2375"
    else:
        status.note = "Docker Engine API is not exposed on localhost:2375"

    return ds, status
